<?php
session_start();if(!isset($_SESSION['user_id'])||$_SESSION['role']!=='patient'){header('Location: ../auth/login.php');exit();}include('../config/database.php');$user_id=(int)$_SESSION['user_id'];$name=$_SESSION['name'];$pq=mysqli_query($conn,"SELECT id FROM patients WHERE user_id=$user_id LIMIT 1");$p=mysqli_fetch_assoc($pq);$patient_id=(int)$p['id'];$q=mysqli_query($conn,"SELECT pr.id,pr.diagnosis,pr.notes,pr.created_at,u.name doctor_name FROM prescriptions pr JOIN doctors dr ON pr.doctor_id=dr.id JOIN users u ON dr.user_id=u.id WHERE pr.patient_id=$patient_id ORDER BY pr.created_at DESC");?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Prescriptions | ClinicCare</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/patient.css"></head><body><div class="patient-layout"><aside class="patient-sidebar"><div class="patient-brand"><div class="patient-brand-icon"><i class="fa-solid fa-plus"></i></div><div><h3>ClinicCare</h3><span>Patient Portal</span></div></div><div class="patient-profile"><div class="patient-avatar-small"><?php echo strtoupper(substr($name,0,1));?></div><div class="patient-profile-info"><strong><?php echo htmlspecialchars($name);?></strong><span>Patient</span></div></div><nav class="patient-nav"><div class="patient-nav-heading">MAIN MENU</div><a href="dashboard.php" class="patient-nav-link">Dashboard</a><a href="book_appointment.php" class="patient-nav-link">Book Appointment</a><a href="appointments.php" class="patient-nav-link">Appointments</a><a href="queue.php" class="patient-nav-link">Live Queue</a><a href="prescriptions.php" class="patient-nav-link active">Prescriptions</a><a href="notifications.php" class="patient-nav-link">Notifications</a></nav><div class="patient-sidebar-bottom"><a href="../auth/logout.php" class="patient-logout"><i class="fa-solid fa-right-from-bracket"></i>Logout</a></div></aside><main class="patient-main"><header class="patient-topbar"><div><h1>Prescriptions</h1><p>View and print prescriptions from your doctor.</p></div></header><div class="patient-content"><section class="patient-card"><div class="patient-card-header"><div><h2>Prescription History</h2><p>Your available prescriptions.</p></div></div><div class="patient-card-body"><div class="rebook-grid"><?php if(mysqli_num_rows($q)){while($pr=mysqli_fetch_assoc($q)){?><div class="patient-card" style="margin:0"><div class="patient-card-header"><div><h2>Dr. <?php echo htmlspecialchars($pr['doctor_name']);?></h2><p><?php echo date('d M Y',strtotime($pr['created_at']));?></p></div></div><div class="patient-card-body"><strong style="font-size:12px;color:var(--cc-navy)">Diagnosis</strong><p style="font-size:11px;color:var(--cc-muted)"><?php echo nl2br(htmlspecialchars($pr['diagnosis']));?></p><?php if($pr['notes']){?><strong style="font-size:12px;color:var(--cc-navy)">Notes</strong><p style="font-size:11px;color:var(--cc-muted)"><?php echo nl2br(htmlspecialchars($pr['notes']));?></p><?php } ?><a href="print_prescription.php?id=<?php echo $pr['id'];?>" class="patient-primary-btn"><i class="fa-solid fa-print"></i> Print Prescription</a></div></div><?php }}else{?><div class="cc-empty" style="grid-column:1/-1"><div class="cc-empty-icon"><i class="fa-solid fa-prescription-bottle-medical"></i></div><h3>No prescriptions</h3><p>Available prescriptions will appear here.</p></div><?php }?></div></div></section></div></main></div></body></html>
